<script lang="ts">
 import {auth} from '#lib/auth.svelte.ts';import {anyApi} from 'convex/server';import {untrack} from 'svelte';let rows=$state<any[]>([]),busy=$state(false),error=$state(''),message=$state(''),confirmation=$state('');
 async function load(){if(auth.client)rows=await auth.client.query(anyApi.privacy.requests,{});}$effect(()=>{if(auth.client)untrack(()=>void load());});
 async function run(task:()=>Promise<void>){busy=true;error='';try{await task();await load();}catch(e){error=(e as Error).message;}finally{busy=false;}}
 async function download(){await run(async()=>{const result:Record<string,unknown>={exportedAt:new Date().toISOString(),site:'https://puntersedge.ewinproject.org'};for(const table of ['profile','user_betslips','saved_slips','ticket_rules','member_profiles','account_access','subscriptions','payments','account_events','user_presence','payment_cases','privacy_requests']){let cursor:string|null=null,done=false;const records:unknown[]=[];while(!done){const page:{page:unknown[];isDone:boolean;continueCursor:string}=await auth.client!.query(anyApi.privacy.exportPage,{table,paginationOpts:{numItems:50,cursor}});records.push(...page.page);done=page.isDone;cursor=page.continueCursor;}result[table]=records;}const url=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='PuntersEdge-personal-data.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message='Export prepared on this device. Keep it private.';});}
</script>
<svelte:head><title>Privacy controls — PuntersEdge</title></svelte:head><section class="surface mx-auto max-w-2xl space-y-5 p-6"><h1 class="text-3xl font-bold">Your data & privacy</h1><p class="text-haze">Export your own application records, or request account erasure. Financial reference records needed for reconciliation are retained without your contact details. <a class="text-model underline" href="/privacy">Read the retention policy</a>.</p>{#if auth.signedIn}<button class="btn-primary" disabled={busy} onclick={download}>{busy?'Working…':'Download my data'}</button><details class="rounded-xl border border-line p-4"><summary class="min-h-11 cursor-pointer font-bold">Request account deletion</summary><p class="mt-3 text-sm text-haze">This requests administrator-reviewed erasure of your profile, slips, saved rules, activity, devices and authentication account. Active access is not refundable automatically. Resolve payment disputes first. You can cancel until processing begins.</p><label class="mt-3 block">Enter DELETE MY ACCOUNT<input class="field mt-2 w-full" bind:value={confirmation} autocomplete="off"/></label><button class="btn-ghost mt-3 text-loss" disabled={busy||confirmation!=='DELETE MY ACCOUNT'} onclick={()=>run(async()=>{await auth.client!.mutation(anyApi.privacy.requestDeletion,{confirmation});confirmation='';message='Deletion request submitted.';})}>Submit deletion request</button></details>{#each rows as row}<div class="rounded-xl border border-line p-4"><p>Deletion request: {row.status}</p>{#if row.status==='requested'}<button class="btn-ghost mt-3" disabled={busy} onclick={()=>run(async()=>{await auth.client!.mutation(anyApi.privacy.cancel,{id:row._id});})}>Cancel request</button>{/if}</div>{/each}{:else}<a class="btn-primary" href="/login?next=/account/privacy">Sign in to manage your data</a>{/if}{#if error}<p role="alert" class="text-loss">{error}</p>{/if}{#if message}<p role="status" class="text-model">{message}</p>{/if}</section>